{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "Versioning is not enabled for the S3 bucket. Without versioning, accidental deletions or overwrites of objects cannot be recovered."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for the S3 bucket. Without logging, it is difficult to track access patterns or detect unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured. This increases the risk of unintentional public exposure of sensitive data."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server-side encryption enabled with a KMS key. This could lead to unencrypted data being stored in the bucket."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration. Without lifecycle rules, old or unused objects may accumulate, increasing storage costs."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
  }, {})

  versioning {
    enabled = true
  }

  logging {
    target_bucket = "${local.resource_prefix.value}-log-bucket"
    target_prefix = "${local.resource_prefix.value}/"
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = "aws/s3"
        sse_algorithm     = "aws:kms"
      }
    }
  }

  lifecycle_rule {
    enabled = true
    expiration {
      days = 365
    }
    noncurrent_version_expiration {
      days = 30
    }
  }
}

resource "aws_s3_bucket_public_access_block" "flowbucket_public_access_block" {
  bucket                  = aws_s3_bucket.flowbucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Enabled versioning, access logging, server-side encryption with KMS, lifecycle rules, and added a public access block for the S3 bucket to address identified security misconfigurations."
}
